from openai import AzureOpenAI

def select_platform_resource(config):
    client = AzureOpenAI(azure_endpoint=config['endpoint'], api_key=config['api_key'], api_version=config.get('api_version', '2024-10-21'))
    deployments = client.deployments.list()
    for deployment in deployments:
        if deployment.model == config['model']:
            return deployment.id
    raise ValueError('Model not found')

from openai import AzureOpenAI

def stream_platform_generation(payload, config):
    client = AzureOpenAI(azure_endpoint=config['endpoint'], api_key=config['api_key'], api_version=config.get('api_version', '2024-10-21'))
    response = client.chat.completions.create(model=config['deployment'], messages=[{'role': 'user', 'content': payload['text']}], stream=True)
    for chunk in response:
        yield chunk

from openai import AzureOpenAI

def collect_platform_metadata(payload, config):
    client = AzureOpenAI(azure_endpoint=config['endpoint'], api_key=config['api_key'], api_version=config.get('api_version', '2024-10-21'))
    response = client.chat.completions.create(model=config['deployment'], messages=[{'role': 'user', 'content': payload['text']}])
    return {'text': response.choices[0].message.content or '', 'usage': response.usage, 'model': response.model}

